/*
# KaamWale marketplace foundation
Creates profiles, categories, professional profiles/services/areas/portfolio, requests, favorites, reviews, notifications, private verification documents, and admin audit logs. Every table uses RLS. Public discovery is limited to active categories and visible professional content; private workflows are scoped to signed-in owners or admins. Verification documents are never public.
*/
create table if not exists public.profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, role text not null default 'customer' check (role in ('customer','professional','admin')), full_name text not null default '', phone text, email text, avatar_url text, city text, area text, pincode text, address text, is_suspended boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text not null default '', icon text not null default 'wrench', is_active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.professional_profiles (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, category_id uuid references public.categories(id) on delete set null, about text not null default '', experience_years integer not null default 0 check (experience_years >= 0), starting_price numeric(10,2) check (starting_price >= 0), service_radius integer not null default 10 check (service_radius >= 0), verification_status text not null default 'pending' check (verification_status in ('pending','verified','rejected')), verification_reason text, availability_status text not null default 'available' check (availability_status in ('available','busy','offline')), is_visible boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.professional_services (id uuid primary key default gen_random_uuid(), professional_id uuid not null references public.professional_profiles(id) on delete cascade, service_name text not null, description text not null default '', price numeric(10,2) check (price >= 0), created_at timestamptz not null default now());
create table if not exists public.service_areas (id uuid primary key default gen_random_uuid(), professional_id uuid not null references public.professional_profiles(id) on delete cascade, city text not null, area text, pincode text, latitude numeric(9,6), longitude numeric(9,6), created_at timestamptz not null default now());
create table if not exists public.portfolio_images (id uuid primary key default gen_random_uuid(), professional_id uuid not null references public.professional_profiles(id) on delete cascade, image_url text not null, created_at timestamptz not null default now());
create table if not exists public.service_requests (id uuid primary key default gen_random_uuid(), customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade, professional_id uuid references public.professional_profiles(id) on delete set null, category_id uuid references public.categories(id) on delete set null, service_name text not null, description text not null default '', requested_date date, requested_time time, address text not null default '', city text not null default '', area text, pincode text, status text not null default 'pending' check (status in ('pending','accepted','rejected','in_progress','completed','cancelled')), customer_notes text, image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.favorites (id uuid primary key default gen_random_uuid(), customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade, professional_id uuid not null references public.professional_profiles(id) on delete cascade, created_at timestamptz not null default now(), unique(customer_id, professional_id));
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), request_id uuid not null unique references public.service_requests(id) on delete cascade, customer_id uuid not null default auth.uid() references auth.users(id) on delete cascade, professional_id uuid not null references public.professional_profiles(id) on delete cascade, rating integer not null check (rating between 1 and 5), review text not null default '', is_published boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, title text not null, message text not null, type text not null default 'general', is_read boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.verification_documents (id uuid primary key default gen_random_uuid(), professional_id uuid not null references public.professional_profiles(id) on delete cascade, document_type text not null, document_url text not null, status text not null default 'pending' check (status in ('pending','approved','rejected')), admin_note text, created_at timestamptz not null default now());
create table if not exists public.admin_logs (id uuid primary key default gen_random_uuid(), admin_id uuid not null default auth.uid() references auth.users(id) on delete restrict, action text not null, target_type text not null, target_id uuid, description text not null default '', created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where user_id = auth.uid() and role = 'admin'); $$;
create index if not exists profiles_location_idx on public.profiles(city, area, pincode); create index if not exists professional_category_idx on public.professional_profiles(category_id); create index if not exists professional_status_idx on public.professional_profiles(verification_status, availability_status); create index if not exists areas_location_idx on public.service_areas(city, area, pincode); create index if not exists requests_customer_idx on public.service_requests(customer_id, status); create index if not exists requests_professional_idx on public.service_requests(professional_id, status);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','categories','professional_profiles','professional_services','service_areas','portfolio_images','service_requests','favorites','reviews','notifications','verification_documents','admin_logs'] LOOP EXECUTE format('alter table public.%I enable row level security', t); END LOOP; END $$;
create policy "profiles public or own" on public.profiles for select to anon,authenticated using (role = 'professional' or user_id = auth.uid() or public.is_admin()); create policy "profiles own insert" on public.profiles for insert to authenticated with check (user_id = auth.uid()); create policy "profiles own update" on public.profiles for update to authenticated using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid() or public.is_admin()); create policy "profiles admin delete" on public.profiles for delete to authenticated using (public.is_admin());
create policy "categories public read" on public.categories for select to anon,authenticated using (is_active or public.is_admin()); create policy "categories admin insert" on public.categories for insert to authenticated with check (public.is_admin()); create policy "categories admin update" on public.categories for update to authenticated using (public.is_admin()) with check (public.is_admin()); create policy "categories admin delete" on public.categories for delete to authenticated using (public.is_admin());
create policy "professionals public read" on public.professional_profiles for select to anon,authenticated using (is_visible or user_id = auth.uid() or public.is_admin()); create policy "professionals own insert" on public.professional_profiles for insert to authenticated with check (user_id = auth.uid()); create policy "professionals own update" on public.professional_profiles for update to authenticated using (user_id = auth.uid() or public.is_admin()) with check (user_id = auth.uid() or public.is_admin()); create policy "professionals admin delete" on public.professional_profiles for delete to authenticated using (public.is_admin());
create policy "services public read" on public.professional_services for select to anon,authenticated using (true); create policy "services own insert" on public.professional_services for insert to authenticated with check (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))); create policy "services own update" on public.professional_services for update to authenticated using (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))) with check (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))); create policy "services own delete" on public.professional_services for delete to authenticated using (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin())));
create policy "areas public read" on public.service_areas for select to anon,authenticated using (true); create policy "areas own insert" on public.service_areas for insert to authenticated with check (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))); create policy "areas own update" on public.service_areas for update to authenticated using (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))) with check (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))); create policy "areas own delete" on public.service_areas for delete to authenticated using (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin())));
create policy "portfolio public read" on public.portfolio_images for select to anon,authenticated using (true); create policy "portfolio own insert" on public.portfolio_images for insert to authenticated with check (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))); create policy "portfolio own delete" on public.portfolio_images for delete to authenticated using (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin())));
create policy "requests participants read" on public.service_requests for select to authenticated using (customer_id=auth.uid() or exists(select 1 from public.professional_profiles p where p.id=professional_id and p.user_id=auth.uid()) or public.is_admin()); create policy "requests customer insert" on public.service_requests for insert to authenticated with check (customer_id=auth.uid()); create policy "requests participants update" on public.service_requests for update to authenticated using (customer_id=auth.uid() or exists(select 1 from public.professional_profiles p where p.id=professional_id and p.user_id=auth.uid()) or public.is_admin()) with check (customer_id=auth.uid() or exists(select 1 from public.professional_profiles p where p.id=professional_id and p.user_id=auth.uid()) or public.is_admin()); create policy "requests customer delete" on public.service_requests for delete to authenticated using (customer_id=auth.uid() or public.is_admin());
create policy "favorites own read" on public.favorites for select to authenticated using (customer_id=auth.uid()); create policy "favorites own insert" on public.favorites for insert to authenticated with check (customer_id=auth.uid()); create policy "favorites own update" on public.favorites for update to authenticated using (customer_id=auth.uid()) with check (customer_id=auth.uid()); create policy "favorites own delete" on public.favorites for delete to authenticated using (customer_id=auth.uid());
create policy "reviews public read" on public.reviews for select to anon,authenticated using (is_published or customer_id=auth.uid() or public.is_admin()); create policy "reviews own insert" on public.reviews for insert to authenticated with check (customer_id=auth.uid()); create policy "reviews own update" on public.reviews for update to authenticated using (customer_id=auth.uid() or public.is_admin()) with check (customer_id=auth.uid() or public.is_admin()); create policy "reviews admin delete" on public.reviews for delete to authenticated using (public.is_admin());
create policy "notifications own read" on public.notifications for select to authenticated using (user_id=auth.uid() or public.is_admin()); create policy "notifications own insert" on public.notifications for insert to authenticated with check (user_id=auth.uid() or public.is_admin()); create policy "notifications own update" on public.notifications for update to authenticated using (user_id=auth.uid() or public.is_admin()) with check (user_id=auth.uid() or public.is_admin()); create policy "notifications own delete" on public.notifications for delete to authenticated using (user_id=auth.uid() or public.is_admin());
create policy "documents private read" on public.verification_documents for select to authenticated using (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))); create policy "documents own insert" on public.verification_documents for insert to authenticated with check (exists(select 1 from public.professional_profiles p where p.id=professional_id and (p.user_id=auth.uid() or public.is_admin()))); create policy "documents admin update" on public.verification_documents for update to authenticated using (public.is_admin()) with check (public.is_admin()); create policy "documents admin delete" on public.verification_documents for delete to authenticated using (public.is_admin());
create policy "logs admin read" on public.admin_logs for select to authenticated using (public.is_admin()); create policy "logs admin insert" on public.admin_logs for insert to authenticated with check (admin_id=auth.uid() and public.is_admin());
insert into public.categories (name,slug,description,icon) values ('Electrician','electrician','Switches, wiring, fans and emergency electrical work.','zap'),('Plumber','plumber','Leak repairs, fittings, tanks and bathroom work.','droplets'),('House Help','house-help','Reliable help for everyday home tasks.','home'),('Carpenter','carpenter','Furniture repair, woodwork and custom fittings.','hammer'),('Painter','painter','Fresh walls, textures and complete home painting.','paintbrush'),('Cleaner','cleaner','Deep cleaning for homes, offices and move-outs.','sparkles'),('AC Technician','ac-technician','AC servicing, installation and repairs.','snowflake'),('Appliance Repair','appliance-repair','Trusted repairs for everyday home appliances.','refrigerator'),('Mechanic','mechanic','Two-wheeler and car servicing near you.','car-front'),('Mason','mason','Construction, tiling and renovation work.','hard-hat'),('Gardener','gardener','Garden care, pruning and balcony greens.','leaf'),('Locksmith','locksmith','Locks, keys and urgent door assistance.','key-round'),('Pest Control','pest-control','Safe pest treatment for homes and businesses.','bug'),('Mover & Packer','mover-packer','Careful local shifting and packing support.','package'),('Computer Repair','computer-repair','Laptop, desktop and network troubleshooting.','laptop'),('Mobile Repair','mobile-repair','Screen, battery and software repairs.','smartphone') on conflict(slug) do nothing;